package ar.org.inclusoft.api.attendance;
import java.time.*; import java.util.*; import jakarta.persistence.*; import ar.org.inclusoft.api.workshop.Workshop; import org.hibernate.annotations.UuidGenerator;
@Entity @Table(name="attendance_sessions") class AttendanceSession {
 @Id @UuidGenerator private UUID id; @ManyToOne(optional=false) @JoinColumn(name="workshop_id") private Workshop workshop; @Column(name="attendance_date",nullable=false) private LocalDate attendanceDate; @Column(length=1000) private String notes; @Column(name="created_by",nullable=false,length=100) private String createdBy; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now(); @OneToMany(mappedBy="session",cascade=CascadeType.ALL,orphanRemoval=true) private List<AttendanceEntry> entries=new ArrayList<>(); protected AttendanceSession(){} AttendanceSession(Workshop w,LocalDate d,String user){workshop=w;attendanceDate=d;createdBy=user;} void update(String n,List<AttendanceEntry> values){notes=n;entries.clear();values.forEach(v->{v.assignTo(this);entries.add(v);});} @PreUpdate void touch(){updatedAt=Instant.now();} UUID getId(){return id;} Workshop getWorkshop(){return workshop;} LocalDate getAttendanceDate(){return attendanceDate;} String getNotes(){return notes;} List<AttendanceEntry> getEntries(){return entries;}
}
